( (SELECT id FROM ref_lab WHERE kode='I027707'), NULL, NULL, NULL, 'Catatan : <BR>Hasil Non Reaktif tidak menyingkirkan kemungkinan terinfeksi SARS-CoV-2 sehingga masih beresiko menularkan<BR>ke orang lain. Hasil Non Reaktif dapat terjadi pada kondisi :<BR>- Seseorang belum/tidak terinfeksi <BR>- Window period(terinfeksi namun antibodi belum terbentuk)<BR>- Immunocompromised<BR>- Kadar antibodi dibawah level deteksi alat <BR><BR>Saran :<BR>- Ulang pemeriksaan rapid tes antibodi 10 hari kemudian<BR>- Tetap menjaga social/physical distancing <BR>- Pertahankan perilaku hidup bersih dan sehat(Cuci tangan, terapkan etika batuk, gunakan masker saat sakit,<BR>  jaga stamina).' ),
( (SELECT id FROM ref_lab WHERE kode='I027708'), NULL, NULL, NULL, 'Saran :<BR>- Lanjutkan dengan pemeriksaan konfirmasi PCR <BR>- Tetap lakukan Social Distancing/isolasi diri.' ),
( (SELECT id FROM ref_lab WHERE kode='I0279'), NULL, NULL, NULL, 'Negatif' ),
( (SELECT id FROM ref_lab WHERE kode='I027906'), NULL, NULL, NULL, '<b>Saran</b>: <br><ul><li>Pemeriksaan konfirmasi dengan pemeriksaan RT-PCR</li><li>Lakukan karantina atau isolasi sesuai dengan kriteria</li><li>Menerapkan PHBS (perilaku hidup bersih dan sehat): mencuci tangan, menerapkan etika batuk, menggunakan masker saat sakit, menjaga stamina), dan <i>physical distancing</i>.</li></ul>' ),
( (SELECT id FROM ref_lab WHERE kode='I027907'), NULL, NULL, NULL, '<b>Catatan :</b><br><ul><li>Hasil negatif tidak menyingkirkan kemungkinan terinfeksi SARS-CoV-2 sehingga masih berisiko menularkan ke orang lain, disarankan tes ulang atau tes konfirmasi dengan NAAT (nucleic acid amplification tests), bila probabilitas pretes relatif tinggi, terutama bila pasien bergejala atau diketahui memiliki kontak dengan orang yang terkonfirmasi COVID-19.</li><li>Hasil negatif dapat terjadi pada kondisi kuantitas antigen pada spesimen dibawah level deteksi alat.</li></ul>' ),
